policies.read_engine:
permit(
  principal,
  action in [
    AgentCore::Action::"engine___audit_case",
    AgentCore::Action::"engine___check_code_pair",
    AgentCore::Action::"engine___check_units",
    AgentCore::Action::"engine___fap_eligibility",
    AgentCore::Action::"engine___hospital_price",
    AgentCore::Action::"engine___explain_rule"
  ],
  resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:us-east-1:ACCOUNT:gateway/cc-gateway"
)
when {
  principal.hasTag("role")
};

policies.case_tools:
permit(
  principal,
  action in [
    AgentCore::Action::"case___get_case",
    AgentCore::Action::"case___save_extraction",
    AgentCore::Action::"case___draft_action"
  ],
  resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:us-east-1:ACCOUNT:gateway/cc-gateway"
)
when {
  principal.hasTag("role") &&
  ["patient", "advocate", "system"].contains(principal.getTag("role"))
};

policies.send_dispute_letter:
permit(
  principal,
  action == AgentCore::Action::"actions___send_dispute_letter",
  resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:us-east-1:ACCOUNT:gateway/cc-gateway"
)
when {
  principal.hasTag("role") &&
  ["patient", "advocate", "system"].contains(principal.getTag("role")) &&
  context.input.approval_token != "" &&
  !context.input.finding_ids.isEmpty() &&
  (
    context.input.recipient_email like "*@nyp.org" ||
    context.input.recipient_email like "*@clevelandclinic.org" ||
    context.input.recipient_email == "countercharge.demo+billing@gmail.com"
  ) &&
  (
    context.input.disputed_amount_cents <= 1000000 ||
    principal.getTag("role") == "advocate"
  )
};

policies.fap_and_itemized:
permit(
  principal,
  action in [
    AgentCore::Action::"actions___submit_fap_application",
    AgentCore::Action::"actions___request_itemized_bill"
  ],
  resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:us-east-1:ACCOUNT:gateway/cc-gateway"
)
when {
  principal.hasTag("role") &&
  ["patient", "advocate", "system"].contains(principal.getTag("role")) &&
  context.input.approval_token != "" &&
  (
    context.input.recipient_email like "*@nyp.org" ||
    context.input.recipient_email like "*@clevelandclinic.org" ||
    context.input.recipient_email == "countercharge.demo+billing@gmail.com"
  )
};

policies.file_escalation:
permit(
  principal,
  action == AgentCore::Action::"actions___file_escalation",
  resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:us-east-1:ACCOUNT:gateway/cc-gateway"
)
when {
  principal.hasTag("role") &&
  ["advocate", "system"].contains(principal.getTag("role")) &&
  context.input.approval_token != "" &&
  !context.input.finding_ids.isEmpty()
};

policies.schedule_followup:
permit(
  principal,
  action == AgentCore::Action::"actions___schedule_followup",
  resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:us-east-1:ACCOUNT:gateway/cc-gateway"
)
when {
  principal.hasTag("role") &&
  ["patient", "advocate", "system"].contains(principal.getTag("role")) &&
  context.input.days >= 1 &&
  context.input.days <= 90
};
